"""Numerical fixtures from the official R functions; no R needed at test time."""
import numpy as np
import pytest
from scipy.optimize import minimize
from scipy.special import expit, logit
from openppi import Mean, PPIData, RoganGladen, MisclassificationMLE, get_method


def data_from_counts(cells, positives, total):
    return PPIData(np.repeat([0, 0, 1, 1], cells),
                   np.repeat([0, 1, 0, 1], cells),
                   np.r_[np.ones(positives), np.zeros(total - positives)])


# Generated by fixtures/generate_misclassification.R; alpha=.05.
FIXTURES = [
    ([40,10,15,35], 90, 200,
     [.49795991394323452,.013147289716534104,.28759239852094393,.70905219356431515],
     [.5000000004250751,.0020791460706710793,.4115699563147385,.5884300445088194,.8000000029386501,.7000000043811133]),
    ([18,12,7,23], 35, 100,
     [0,.082465142930416666,0,1],
     [.4450000347234466,.004002415285536053,.3267427539368333,.5698322906924795,.7297297596605247,.646067444096378]),
    ([70,5,10,15], 120, 150,
     [1,.03779217961536654,0,1],
     [.474999944128747,.0035896909006888013,.3610111219637833,.5916549100596722,.7333333821531604,.8842104565917085]),
]


@pytest.mark.parametrize('cells,u,n,rg,mle', FIXTURES)
def test_official_r_fixtures(cells, u, n, rg, mle):
    data = data_from_counts(cells,u,n)
    for name, expected in [('RG', rg), ('MLE', mle)]:
        r = get_method(name).inference(data,target=Mean())
        actual = [r.estimate,r.standard_error**2,*r.confidence_interval]
        if name=='MLE': actual += [r.diagnostics['specificity'],r.diagnostics['sensitivity']]
        np.testing.assert_allclose(actual,expected,rtol=2e-6,atol=2e-7)
        assert r.method == name
        assert r.diagnostics['labeled_count']==len(data.labels)


def test_mle_is_joint_likelihood_maximizer():
    data=data_from_counts([18,12,7,23],35,100)
    r=MisclassificationMLE()(data,target=Mean())
    def loss(abc):
        th,q0,q1=expit(abc)
        p=th*q1+(1-th)*(1-q0)
        probs=[(1-th)*q0,(1-th)*(1-q0),th*(1-q1),th*q1]
        return -(np.array([18,12,7,23])@np.log(probs)+35*np.log(p)+65*np.log1p(-p))
    fit=minimize(loss,logit([.5,.7,.7]),method='BFGS')
    assert -fit.fun==pytest.approx(r.diagnostics['log_likelihood'],abs=1e-8)
    np.testing.assert_allclose(expit(fit.x),[r.estimate,r.diagnostics['specificity'],r.diagnostics['sensitivity']],atol=1e-6)


@pytest.mark.parametrize('method',[RoganGladen,MisclassificationMLE])
def test_hard_predictions_required(method):
    for f,g in [([.1,.8],[0,1]),([0,1],[.1,.8])]:
        with pytest.raises(ValueError,match='binary predictions'):
            method()(PPIData([0,1],f,g),target=Mean())


def test_degenerate_inputs_and_orientation():
    with pytest.raises(ValueError,match='both label classes'):
        RoganGladen()(PPIData([1,1],[0,1],[0,1]),target=Mean())
    random=data_from_counts([10,10,10,10],20,40)
    with pytest.raises(ValueError,match='Youden index'):
        RoganGladen()(random,target=Mean())
    with pytest.raises(ValueError,match='positive judge orientation'):
        MisclassificationMLE()(random,target=Mean())
    with pytest.raises(ValueError,match='four calibration cells'):
        MisclassificationMLE()(data_from_counts([10,0,0,10],20,40),target=Mean())
    reverse=data_from_counts([5,15,15,5],20,40)
    assert RoganGladen()(reverse,target=Mean()).diagnostics['youden_index']<0
    for bad in [0,-1,1,np.nan]:
        with pytest.raises(ValueError): RoganGladen(eps_J=bad)


def test_alpha_adjustment_and_custom_interval():
    data=data_from_counts([40,10,15,35],90,200)
    low=RoganGladen()(data,target=Mean(),alpha=.01)
    high=RoganGladen()(data,target=Mean(),alpha=.2)
    assert low.estimate!=high.estimate
    seen=[]
    def interval(point,se,alpha,values=None):
        seen.append((point,se,alpha)); return (point-se,point+se)
    for method in [RoganGladen,MisclassificationMLE]:
        r=method(interval=interval)(data,target=Mean(),alpha=.1)
        assert seen[-1]==(r.estimate,r.standard_error,.1)


@pytest.mark.slow
def test_model_coverage():
    rng=np.random.default_rng(53)
    covered=np.zeros(2)
    for _ in range(200):
        y=rng.binomial(1,.4,2000)
        f=rng.binomial(1,np.where(y,.8,.2))
        data=PPIData(y[:400],f[:400],f[400:])
        for j,method in enumerate([RoganGladen,MisclassificationMLE]):
            r=method()(data,target=Mean())
            covered[j]+=r.confidence_interval[0]<=.4<=r.confidence_interval[1]
    assert np.all(covered/200>.90),covered
